      dependencies: [{ method: "GET", path: "/v1/dependencies" }, { method: "POST", path: "/v1/dependencies" }, { method: "GET", path: "/v1/dependencies/:dependencyId" }, { method: "PATCH", path: "/v1/dependencies/:dependencyId" }, { method: "GET", path: "/v1/dependencies/:dependencyId/spend-block" }, { method: "GET", path: "/v1/sit-exceptions" }, { method: "POST", path: "/v1/sit-exceptions" }],
