      reports: [{ method: "GET", path: "/v1/reports/portfolio" }, { method: "GET", path: "/v1/reports" }, { method: "POST", path: "/v1/reports" }, { method: "POST", path: "/v1/reports/:reportId/publish" }],
      stagegates: [{ method: "GET", path: "/v1/stage-gates" }, { method: "POST", path: "/v1/stage-gates" }, { method: "GET", path: "/v1/stage-gates/:gateId" }, { method: "GET", path: "/v1/stage-gates/:gateId/evidence" }, { method: "POST", path: "/v1/stage-gates/:gateId/evidence" }, { method: "POST", path: "/v1/stage-gates/:gateId/outcome" }],
